    const sizeMB = (parsedTorrent.pieceLength / (1024 * 1024)).toFixed(1);
    const maxMB = (MAX_PIECE_SIZE / (1024 * 1024)).toFixed(0);
    const error = new Error(
      `Torrent piece size (${sizeMB}MB) exceeds maximum supported size (${maxMB}MB)`
    );
