async function parseTorrentInput(magnetOrBuffer, hasher) {
  if (typeof magnetOrBuffer === "string") {
    let magnetLink = magnetOrBuffer;
    if (looksLikeBareInfoHash(magnetOrBuffer)) {
      magnetLink = bareHashToMagnet(magnetOrBuffer);
    }
    const parsed = parseMagnet(magnetLink);
    const infoHash = fromHex(parsed.infoHash);
    return {
      infoHash,
      infoHashStr: parsed.infoHash,
      announce: parsed.announce || [],
      magnetLink,
      magnetDisplayName: parsed.name,
      magnetPeerHints: parsed.peers,
      magnetUrlSeeds: parsed.urlList,
      magnetSelectOnly: parsed.selectOnly
    };
  } else {
    const parsedTorrent = await TorrentParser.parse(magnetOrBuffer, hasher);
    const infoHashStr = infoHashFromBytes(parsedTorrent.infoHash);
    return {
      infoHash: parsedTorrent.infoHash,
      infoHashStr,
      announce: parsedTorrent.announce,
      torrentFileBase64: toBase64(magnetOrBuffer),
      infoBuffer: parsedTorrent.infoBuffer,
      torrentFileBuffer: magnetOrBuffer,
      // Store raw buffer for persistence
      parsedTorrent
    };
  }
}

